def transform(grid):
    # Decode each 3x3 tile, retaining any marker color distinct from the
    # two background/pattern colors (0 and 5); otherwise output 0.
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            markers = [grid[i][j]
                       for i in range(r, min(r + 3, len(grid)))
                       for j in range(c, min(c + 3, len(grid[0])))
                       if grid[i][j] not in (0, 5)]
            row.append(markers[0] if markers else 0)
        out.append(row)
    return out
